// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
/// @title Foundation docs
/// @author Zig Port
/// @notice Base contract notice.
/// @dev Base contract details.
/// @custom:security reviewed
abstract contract Base {
    /// @notice Initialize the counter.
    /// @dev Stores the initial value.
    /// @param seed Initial counter.
    constructor(uint256 seed) { count = seed; }

    /// @notice Read the counter.
    /// @dev Tracks the current counter.
    /// @return current counter value
    uint256 public count;

    /// @notice A move occurred.
    /// @dev Emitted for every move.
    /// @param from Source account.
    /// @param amount Moved amount.
    event Moved(address indexed from, uint256 amount);

    /// @notice A bad value was supplied.
    /// @dev Rejects invalid input.
    /// @param code Rejection code.
    error Bad(uint256 code);

    /// @notice Compute the result.
    /// @dev Returns its input.
    /// @param x Input value.
    /// @return result Computed value.
    function f(uint256 x) public virtual returns (uint256 result) { return x; }

    /// @notice Double a value.
    /// @dev This documentation is inherited implicitly.
    /// @param value Input value.
    /// @return doubled Doubled value.
    function g(uint256 value) public pure virtual returns (uint256 doubled) { return value * 2; }
}

contract Derived is Base {
    constructor() Base(7) {}

    /// @inheritdoc Base
    function f(uint256 renamed) public pure override returns (uint256 output) { return renamed; }

    function g(uint256 value) public pure override returns (uint256 doubled) { return value * 2; }
}
